        .with_env_filter(tracing_subscriber::EnvFilter::try_from_default_env()
            .unwrap_or_else(|_| "compose_session=debug,tower_http=debug".into()))
        .init();
    let database_url = std::env::var("DATABASE_URL")
        .unwrap_or_else(|_| "postgres://compose:compose@localhost:5432/compose".to_string());
    let pool = create_pool(&database_url).await;
    run_migrations(&pool).await;
    let app_state = AppState::new(pool);
    let app_router = router(app_state);
    let addr: std::net::SocketAddr = std::env::var("LISTEN_ADDR")
        .unwrap_or_else(|_| "0.0.0.0:8080".to_string())
        .parse().expect("invalid LISTEN_ADDR");
    tracing::info!("compose-session listening on {}", addr);
    let listener = tokio::net::TcpListener::bind(addr).await.unwrap();
    axum::serve(listener, app_router).await.unwrap();
}

