    #[test]
    fn metabolism_diff_roundtrip_commands() {
        let diff = load_metabolism_diff_json();
        let mut commands: Vec<DomainCommand> = Vec::new();
        if let Some(removed) = diff.get("types").and_then(|t| t.get("removed")).and_then(|r| r.as_array()) {
            for r in removed {
                if let Some(guid_str) = r.get("guid").and_then(|g| g.as_str()) {
                    if let Ok(guid) = Uuid::parse_str(guid_str) {
                        commands.push(DomainCommand::DeleteType(DeleteEntityPayload { entity_id: guid }));
                    }
                }
            }
        }
        if let Some(updated) = diff.get("types").and_then(|t| t.get("updated")).and_then(|u| u.as_array()) {
            for u in updated {
                if let Some(guid_str) = u.get("guid").and_then(|g| g.as_str()) {
                    if let Ok(guid) = Uuid::parse_str(guid_str) {
                        commands.push(DomainCommand::PatchType(PatchEntityPayload {
                            entity_id: guid, fields: u.clone(),
                        }));
                    }
                }
            }
        }
        let batch = DomainCommand::Batch(BatchPayload { commands: commands.clone() });
        let json = serde_json::to_string(&batch).unwrap();
        let back: DomainCommand = serde_json::from_str(&json).unwrap();
        assert!(matches!(back, DomainCommand::Batch(_)));
    }

