    ("10min", 600),
    ("30min", 1800),
    ("1h", 3600),
    ("5h", 18000),
    ("1d", 86400),
    ("3d", 259200),
    ("7d", 604800),
    ("1mo", 2592000),
    ("6mo", 15552000),
    ("1y", 31536000),
];

