    let types = kit["types"].as_array().unwrap();
    assert_eq!(types.len(), 1);
    assert_eq!(types[0]["name"].as_str().unwrap(), "APIType");

    // Compact history
    let resp = client.post(format!("{}/sessions/{}/history/compact", base, session_id))
        .send().await.unwrap();
    assert_eq!(resp.status(), 200);
}

